node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get full user details
const user = db.prepare(\"SELECT * FROM users WHERE user_id = ?\").get('user_58b0a2d6');
console.log('=== USER PROFILE ===');
console.log(JSON.stringify(user, null, 2));

// Get payment methods
const payments = db.prepare(\"SELECT * FROM rt_payment_methods WHERE user_id = ?\").all('user_58b0a2d6');
console.log('\n=== PAYMENT METHODS ===');
console.log(JSON.stringify(payments, null, 2));

// Get orders
const orders = db.prepare(\"SELECT order_id, status, order_date, total_paid, shipping_method FROM orders WHERE customer_id = ?\").all('user_58b0a2d6');
console.log('\n=== ORDERS ===');
console.log(JSON.stringify(orders, null, 2));

// Get cart
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = ?\").get('user_58b0a2d6');
console.log('\n=== CART ===');
console.log(JSON.stringify(cart, null, 2));

// Get cart items
if (cart) {
  const cartItems = db.prepare(\"SELECT ci.*, p.name as product_name, p.price, p.category FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?\").all(cart.cart_id);
  console.log('\n=== CART ITEMS ===');
  console.log(JSON.stringify(cartItems, null, 2));
}

// Get promotions
const promos = db.prepare(\"SELECT * FROM promotions\").all();
console.log('\n=== ALL PROMOTIONS ===');
console.log(JSON.stringify(promos, null, 2));
"
